// src/pages/SDM.jsx
import React, { useState, useEffect, useRef } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { useUI } from "../context/UIContext";
import Button from "../components/common/Button";
import Card from "../components/common/Card";
import * as sdmData from "../constants/sdm";

import eveVideo from "../assets/eve_sdm_talk.mp4";

const SDM = () => {
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const { setHeroData } = useUI();
  const videoRef = useRef(null);

  const step = searchParams.get("step") || "SELECT";
  const topicParam = searchParams.get("topic") || "";

  const [isPlaying, setIsPlaying] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [selectedTopicId, setSelectedTopicId] = useState(() => {
    if (topicParam === "dcis" || topicParam === "bctsm") return topicParam;
    if (topicParam === "bct_sm") return "bctsm";
    return "";
  });

  const [pureSpeechText, setPureSpeechText] = useState("");
  const [currentSubtitle, setCurrentSubtitle] = useState("");
  const [sentences, setSentences] = useState([]);

  const localTopicList = [
    {
      id: "dcis",
      title: sdmData.topicDescriptions?.dcis?.label,
      description: sdmData.topicDescriptions?.dcis?.description,
      content:
        sdmData.topicDescriptions?.dcis?.content || sdmData.introTextDCIS,
    },
    {
      id: "bctsm",
      title: sdmData.topicDescriptions?.bctsm?.label,
      description: sdmData.topicDescriptions?.bctsm?.description,
      content:
        sdmData.topicDescriptions?.bctsm?.content || sdmData.introTextBctSm,
    },
  ];

  useEffect(() => {
    setHeroData(null);

    let stepIntroText = "";
    if (step === "SELECT") {
      stepIntroText =
        "請選擇您想了解的主題。點選下方以查看詳細的手術決策資訊，可點擊影片重複聆聽導覽。";
    } else if (step === "INTRO" && selectedTopicId) {
      const currentTopic = localTopicList.find((t) => t.id === selectedTopicId);
      stepIntroText = currentTopic ? currentTopic.content : "";
    }

    if (!stepIntroText) return;

    const cleanedText = stepIntroText.replace(/<[^>]*>/g, "").trim();
    setPureSpeechText(cleanedText);

    const sentenceArray = cleanedText.match(
      /[^。？！，、\n]+[。？！，、]?/g,
    ) || [cleanedText];
    let accumulatedLength = 0;
    const mappedSentences = sentenceArray
      .map((sentence) => {
        const startIdx = accumulatedLength;
        accumulatedLength += sentence.length;
        return {
          text: sentence.trim(),
          start: startIdx,
          end: accumulatedLength,
        };
      })
      .filter((s) => s.text.length > 0);

    setSentences(mappedSentences);
    handlePlaySpeech(cleanedText, mappedSentences);
    window.scrollTo(0, 0);

    return () => {
      if (window.speechSynthesis) window.speechSynthesis.cancel();
    };
  }, [step]);

  const handlePlaySpeech = (text, currentSentences = sentences) => {
    if (!window.speechSynthesis || !videoRef.current || !text) return;
    window.speechSynthesis.cancel();

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = "zh-TW";
    utterance.rate = 1.0;

    utterance.onstart = () => {
      setIsPlaying(true);
      setIsPaused(false);
      if (videoRef.current) {
        videoRef.current.muted = true;
        videoRef.current.play().catch((err) => console.log(err));
      }
    };

    utterance.onboundary = (event) => {
      const currentIndex = event.charIndex;
      const activeSentence = currentSentences.find(
        (s) => currentIndex >= s.start && currentIndex < s.end,
      );
      if (activeSentence) setCurrentSubtitle(activeSentence.text);
    };

    utterance.onend = () => {
      setIsPlaying(false);
      setIsPaused(false);
      setCurrentSubtitle("");
      if (videoRef.current) {
        videoRef.current.pause();
        videoRef.current.currentTime = 0;
      }
    };

    utterance.onerror = () => {
      setIsPlaying(false);
      setIsPaused(false);
      setCurrentSubtitle("");
      if (videoRef.current) videoRef.current.pause();
    };

    window.speechSynthesis.speak(utterance);
  };

  const handleTogglePlay = (e) => {
    e.stopPropagation();
    if (!window.speechSynthesis) return;

    if (isPlaying && !isPaused) {
      window.speechSynthesis.pause();
      if (videoRef.current) videoRef.current.pause();
      setIsPaused(true);
    } else if (isPlaying && isPaused) {
      window.speechSynthesis.resume();
      if (videoRef.current)
        videoRef.current.play().catch((err) => console.log(err));
      setIsPaused(false);
    } else {
      handlePlaySpeech(pureSpeechText);
    }
  };

  const handleSelectTopic = (e, id) => {
    e.stopPropagation();
    setSelectedTopicId(id);
    setSearchParams({ step: "SELECT", topic: id });
  };

  const handleConfirmTopic = () => {
    if (!selectedTopicId) return alert("請先選擇一個主題");
    if (window.speechSynthesis) window.speechSynthesis.cancel();
    setSearchParams({ step: "INTRO", topic: selectedTopicId });
  };

  const currentTopic = localTopicList.find((t) => t.id === selectedTopicId);

  return (
    <div
      style={{
        width: "100%",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
      }}
    >
      {/* 注入一組乾淨、絕對不汙染、完全對齊 Selection 圓角與陰影的樣式 */}
      <style>{`
        .sdm-main-card {
          width: 100%;
          background: #ffffff;
          border-radius: 32px;
          overflow: hidden;
          display: flex;
          flex-direction: column;
          box-sizing: border-box;
        }
        .sdm-video-container {
          width: 100%;
          position: relative;
          aspect-ratio: 4 / 3;
          overflow: hidden;
          background-color: #ffffff;
        }
        .sdm-video-element {
          width: 100%;
          height: 100%;
          object-fit: cover;
          object-position: center 20%;
          display: block;
        }
        .sdm-content-body {
          width: 100%;
          padding: 32px 24px;
          box-sizing: border-box;
        }
        .sdm-title {
          font-size: 1.35rem;
          color: #333333;
          text-align: center;
          margin: 0 0 10px 0;
          font-weight: 600;
          letter-spacing: 0.5px;
        }
        .sdm-subtitle {
          font-size: 0.88rem;
          color: #666666;
          text-align: center;
          margin: 0 0 28px 0;
          line-height: 1.5;
        }
        .sdm-card-stack {
          display: flex;
          flex-direction: column;
          gap: 16px;
          margin-bottom: 32px;
        }
        .sdm-action-group {
          display: flex;
          flex-direction: column;
          gap: 14px;
          width: 100%;
        }
        .sdm-badge-audio {
          position: absolute;
          top: 16px;
          left: 16px;
          background: rgba(0, 0, 0, 0.55);
          padding: 5px 10px;
          border-radius: 20px;
          color: #fff;
          font-size: 0.7rem;
          display: flex;
          align-items: center;
          gap: 6px;
          backdrop-filter: blur(4px);
          z-index: 10;
        }
        .sdm-badge-dot {
          width: 6px;
          height: 6px;
          background-color: #22c55e;
          border-radius: 50%;
        }
        .sdm-badge-dot-paused {
          width: 6px;
          height: 6px;
          background-color: #94a3b8;
          border-radius: 50%;
        }
        .sdm-btn-ctrl {
          position: absolute;
          top: 16px;
          right: 16px;
          background: rgba(0, 0, 0, 0.55);
          backdrop-filter: blur(4px);
          border: 1px solid rgba(255, 255, 255, 0.25);
          color: #ffffff;
          padding: 5px 12px;
          border-radius: 20px;
          font-size: 0.75rem;
          cursor: pointer;
          z-index: 10;
        }
        .sdm-caption-box {
          position: absolute;
          bottom: 12px;
          left: 50%;
          transform: translateX(-50%);
          width: 90%;
          background: rgba(0, 0, 0, 0.75);
          padding: 8px 12px;
          border-radius: 8px;
          z-index: 5;
        }
        .sdm-caption-text {
          color: #ffffff;
          font-size: 0.85rem;
          margin: 0;
          text-align: center;
          line-height: 1.4;
        }
        .sdm-intro-box {
          margin-bottom: 28px;
        }
        .sdm-intro-box h3 {
          font-size: 1.2rem;
          color: #333333;
          margin-bottom: 14px;
          font-weight: 600;
        }
        .sdm-intro-text {
          font-size: 0.95rem;
          color: #444444;
          line-height: 1.6;
        }
      `}</style>

      {/* 白色主要卡片（由外層原本運作完美的 Wrapper 來接管它的長寬，不自行追加干擾） */}
      <div className="sdm-main-card">
        {/* 上半部：影片區 */}
        <div className="sdm-video-container">
          <video
            ref={videoRef}
            src={eveVideo}
            playsInline
            webkit-playsinline="true"
            preload="auto"
            loop
            className="sdm-video-element"
          />

          {isPlaying && currentSubtitle && (
            <div className="sdm-caption-box">
              <p className="sdm-caption-text">{currentSubtitle}</p>
            </div>
          )}

          {isPlaying && (
            <div className="sdm-badge-audio">
              <span
                className={isPaused ? "sdm-badge-dot-paused" : "sdm-badge-dot"}
              ></span>
              {isPaused ? "已暫停" : "說明中"}
            </div>
          )}

          <button className="sdm-btn-ctrl" onClick={handleTogglePlay}>
            {isPlaying && !isPaused ? "⏸ 暫停" : "▶️ 播放"}
          </button>
        </div>

        {/* 下半部：內容區 */}
        <div className="sdm-content-body">
          {step === "SELECT" ? (
            <div>
              <h2 className="sdm-title">請選擇您想了解的主題</h2>
              <p className="sdm-subtitle">
                點選下方以查看詳細的手術決策資訊，可點擊影片重複聆聽導覽。
              </p>

              <div className="sdm-card-stack">
                {localTopicList.map((item) => (
                  <Card
                    key={item.id}
                    title={item.title}
                    description={item.description}
                    isActive={selectedTopicId === item.id}
                    onClick={(e) => handleSelectTopic(e, item.id)}
                  />
                ))}
              </div>

              <div className="sdm-action-group">
                <Button onClick={handleConfirmTopic} fullWidth>
                  確認選擇並查看詳情 ➔
                </Button>
                <Button
                  variant="outline"
                  onClick={() => navigate("/selection")}
                  fullWidth
                >
                  返回重新選擇方案
                </Button>
              </div>
            </div>
          ) : (
            <div>
              <div className="sdm-intro-box">
                <h3>{currentTopic?.title}</h3>
                <div
                  className="sdm-intro-text"
                  dangerouslySetInnerHTML={{ __html: currentTopic?.content }}
                />
              </div>

              <div className="sdm-action-group">
                <Button
                  onClick={() =>
                    navigate(
                      `/questionnaire?topic=${selectedTopicId === "bctsm" ? "bct_sm" : "dcis"}`,
                    )
                  }
                  fullWidth
                >
                  開始填寫決策評估表 ➔
                </Button>
                <Button
                  variant="outline"
                  onClick={() =>
                    setSearchParams({ step: "SELECT", topic: selectedTopicId })
                  }
                  fullWidth
                >
                  返回重新選擇主題
                </Button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SDM;
